      const rows = prof.map(([a, r]) => Array.from({ length: 14 }, (_, i) => { const th = (i / 14) * TAU; return axisC.clone().add(new V3(r * Math.sin(th), a, r * 0.96 * Math.cos(th) + 0.004)); }));
