      B.add(g, { ex: GEAR.fabric, color: _c.setRGB(0.13, 0.13, 0.15), weights: () => [[dy > 0 ? 'thighR' : 'shinR', 0.75], [dy > 0 ? 'shinR' : 'thighR', 0.25]] });
