      const g = new THREE.Group(); g.position.copy(pd.pivot);
      const mat = pd.mat === 'opponentInk' ? weaponOpponentMaterial(this, getInkMaterial, G.teamColors) : pd.mat === 'ink' ? getInkMaterial(this.color) : pd.mat === 'lamp' ? makeLampMaterial(pd.lamp) : getPlasticMaterial();
