      const lagZ = spr(sp, S_LAGZ, clamp(-this.kaz * 0.0012, -0.055, 0.07) * g, 2.3, 0.6, dt);
      const lagX = spr(sp, S_LAGX, clamp(-this.kax * 0.0012, -0.05, 0.05) * g, 2.3, 0.6, dt);
      P[HIPS_P + 2] += lagZ; P[HIPS_P] += lagX;
