    // ---------------- tired / goo posture
    if (this.wTired > 0.01) { const w = this.wTired; P[SPINE] += 0.1 * w; P[CHEST] += 0.08 * w; P[NECK] += 0.05 * w; P[HIPS_P + 1] -= 0.02 * w; P[CLAVL + 2] -= 0.05 * w; P[CLAVR + 2] += 0.05 * w; }

