    if (tr[T_THROW] < 0.62) this._poseThrow(P, tr[T_THROW]);
    if (tr[T_SPAWN] < 1.4) this._poseSpawn(P, tr[T_SPAWN]);
    if (tr[T_LEAP] < 1.9) this._poseLeap(P, tr[T_LEAP]);
