      const lf = ld > 0 ? FOOTL : FOOTR, lr = ld > 0 ? FOOTLR : FOOTRR, tf = ld > 0 ? FOOTR : FOOTL, tr2 = ld > 0 ? FOOTRR : FOOTLR;
