  if(!this.active||this.character.sqScale<=0.001)return false;
  let name,frame;
  if(this.manual?.squid){name=this.manual.name;frame=this.manual.frame;}
  else{
   if(this.formEvent&&this.formKid&&this.formTime<this.formDuration){name='Sqd_ToHuman';frame=Math.min(this.formTime*HOST_MOTION.fps,Math.max(0,this.squidBank.clips.get(name).frames-1));}
   else if(this.formEvent&&this.formTime<this.squidBank.clips.get(this.formKid?'Sqd_ToHuman':'Sqd_ToSquid').frames/HOST_MOTION.fps){name=this.formKid?'Sqd_ToHuman':'Sqd_ToSquid';frame=this.formTime*HOST_MOTION.fps;}
   else if(!this.grounded){name='Sqd_Jump';frame=this.airTime*HOST_MOTION.fps;}
   else if(this.landTime<this.squidBank.clips.get('Sqd_Jump_Ed').frames/HOST_MOTION.fps){name='Sqd_Jump_Ed';frame=this.landTime*HOST_MOTION.fps;}
   else{
