   }
   if(frame===null)frame=this.squidFrame;
   this.squidBank.sample(name,frame,this.squidPose);
   if((name==='Sqd_ToHuman'||name==='Sqd_ToSquid'&&this.returnInterrupted)&&this.formTime<this.formDuration){const out=this.squidBlendPose||(this.squidBlendPose=new SourcePose(this.squidBank));out.copy(this.previousSquid).mix(this.squidPose,smooth5(this.formTime/this.formDuration));this.squidPose.copy(out).fk();}
   else if(this.squidBlendTime<HOST_MOTION.transitionSeconds&&!name.startsWith('Sqd_To')){const out=this.squidBlendPose||(this.squidBlendPose=new SourcePose(this.squidBank));out.copy(this.previousSquid).mix(this.squidPose,SMOOTH(this.squidBlendTime/HOST_MOTION.transitionSeconds));this.squidPose.copy(out).fk();}
