  for (let j = 0; j < NC; j++) {
    const jn = (j + 1) % NC;
    for (let i = 0; i < NRow - 1; i++) {
      const a = j * NRow + i, c = jn * NRow + i, b2 = j * NRow + i + 1, d = jn * NRow + i + 1;
      idx.push(a, b2, c, c, b2, d);
