    this.RP = new Float32Array(RN * 3); this.R0 = new Float32Array(RN); this.R1 = new Float32Array(RN);
    this.RA = new Float32Array(RN).fill(1e9); this.RL = new Float32Array(RN); this.rNext = 0;
