    this.splats.receiveShadow = true;
    this.mesh.renderOrder = 1;
  }
  _slot() { for (let i = this._queueFirstFree ?? 0; i < this.N; i++) if (!this.K[i]) return i; return -1; }
  drop(x, y, z, vx, vy, vz, r, kind = 1, life = 6) {
    const i = this._slot(); if (i < 0) return -1;
    this._iwFxIdle = false;
    const i3 = i * 3;
    this.P[i3] = x; this.P[i3 + 1] = y; this.P[i3 + 2] = z;
    this.V[i3] = vx; this.V[i3 + 1] = vy; this.V[i3 + 2] = vz;
    this.R[i] = r; this.A[i] = 0; this.L[i] = life; this.S[i] = this.rand() * TAU; this.K[i] = kind; this._queueFirstFree = this.K[i] ? i + 1 : i;
