    for (const m of [this.mesh, this.splats, this.rings]) { for (let i = 0; i < m.instanceMatrix.count; i++) m.setMatrixAt(i, ZERO_M); m.count = 0; }
  }
  _land(i, k, x, y, z) {
    const r = this.R[i], rnd = this.rand;
    if (k === 1) this.splat(x, y, z, r * 2.5, 1.4 + rnd() * 0.9);
    else if (k === 4) { this.splat(x, y, z, r * 2.1, 1.1 + rnd() * 0.5); this.ripple(x, y, z, 0.02, 0.2 + r * 3, 0.5); }
    else if (k === 2) {
      this.splat(x, y, z, r * 3.3, 3.4 + rnd());
      this.ripple(x, y, z, r, 0.55 + r * 4, 0.75);
      const n = 9;
      for (let q = 0; q < n; q++) {
        const a = (q / n) * TAU + rnd() * 0.6, sp = 0.9 + rnd() * 1.3, sa = Math.sin(a), ca = Math.cos(a);
