            const dx = x - D.x, dz = (z - D.z) / (D.zs || 1);   // zs: oval decks (lobby stage)
            if (dx * dx + dz * dz < D.r * D.r) { landed = true; this.K[i] = 0; this._queueFirstFree = Math.min(this._queueFirstFree, i); this.mesh.setMatrixAt(i, ZERO_M); this._land(i, k, x, D.y, z); break; }
