            -_d.x * (0.6 + r()) + _d.z * side * (0.4 + r() * 0.5), 1.1 + r() * 1.3, -_d.z * (0.6 + r()) - _d.x * side * (0.4 + r() * 0.5), 0.01 + r() * 0.012, 1, 2);
