          const x = (at - ant) / T;
          if (x < 1) { y = 4 * H * x * (1 - x); vy = (4 * H * (1 - 2 * x)) / T; air = true; twirl = TAU * eInOut(x); sy = 1 + 0.1 * c01(vy / 2.2) - 0.05 * c01(-vy / 2.2); }
          else if (A.flag < 2) { A.flag = 2; M.c.trigger('land', 5); fx.crown(P.x, P.y, P.z, 0.5, 10, 0.3); M.c.trigger('wink'); }
