    marina: { channel: '#0b4552', shade: '#05121a', calm: 0.55, lap: 1.0, caustic: 2.0, wet: 0.5 },
  },
  sunset: {
    // golden key vs indigo fill: the low sun paints every face that turns to it orange, shade falls to a cool blue (the
