    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(B.pos, 3)); B.pos = null;
    g.setAttribute('normal', new THREE.Float32BufferAttribute(B.nor.finish(Float32Array).buffer, 3)); B.nor = null;
    g.setAttribute('color', new THREE.Float32BufferAttribute(B.col.finish(Float32Array).buffer, 3)); B.col = null;
    g.setAttribute('paintUv', new THREE.Float32BufferAttribute(B.puv.finish(Float32Array).buffer, 2)); B.puv = null;
    g.setAttribute('lightUv', new THREE.Float32BufferAttribute(B.luv.finish(Float32Array).buffer, 2)); B.luv = null;
    g.setAttribute('faceUv', new THREE.Float32BufferAttribute(B.fuv.finish(Float32Array).buffer, 2)); B.fuv = null;
    g.setAttribute('faceData', new THREE.Float32BufferAttribute(B.fdat.finish(Float32Array).buffer, 4)); B.fdat = null;
    g.setAttribute('faceFlags', new FlagAttribute(B.fflag.finish(FlagAttribute === THREE.Int8BufferAttribute ? Int8Array : Float32Array).buffer, 3, false)); B.fflag = null;
    g.setAttribute('faceTan', new THREE.Float32BufferAttribute(B.ftan.finish(Float32Array).buffer, 3)); B.ftan = null;
    g.setIndex(B.idx.maximum >= 65535
      ? new THREE.Uint32BufferAttribute(B.idx.finish(Uint32Array).buffer, 1)
      : new THREE.Uint16BufferAttribute(B.idx.finish(Uint16Array).buffer, 1));
    g.computeBoundingSphere();
    this.renderTris = B.idx.length / 3;
    B.idx = null;
    return g;
  }

  // Highest walkable surface under (x,z) below yMax (used by nav + spawns). Returns y or -Infinity.
  groundHeight(x, z, yMax = 50) {
    let best = -Infinity;
    const ids = this.queryBlocks(x - 0.01, z - 0.01, x + 0.01, z + 0.01, this._qtmp2 || (this._qtmp2 = []));
    for (const id of ids) {
      const b = this.blocks[id];
      if (!b.solid) continue;
      // intersect vertical line with the block's top face plane
      const n = b.axes[1];
      if (n.y < 0.5) continue;
      const top = _v.copy(b.center).addScaledVector(n, b.half.y);
      // plane: n·(p - top) = 0 → y = top.y - (n.x (x-top.x) + n.z (z-top.z)) / n.y
      const y = top.y - (n.x * (x - top.x) + n.z * (z - top.z)) / n.y;
      _v2.set(x, y - 0.01, z);
      if (y <= yMax && y > best && this.pointInBlock(b, _v2, 0.001)) best = y;
    }
    return best;
  }
}

function mirrorDef(d) {
  const mural = d.mural ? d.mural.map((m) => ({ ...m, n: [-m.n[0], m.n[1], -m.n[2]] })) : undefined;
  const noPaint = d.noPaint ? d.noPaint.map((m) => [-m[0], m[1], -m[2]]) : undefined;
  if (d.kind === 'box') {
    return { ...d, mural, noPaint, min: [-d.max[0], d.min[1], -d.max[2]], max: [-d.min[0], d.max[1], -d.min[2]] };
  }
  if (d.kind === 'obox') return { ...d, mural, noPaint, center: [-d.center[0], d.center[1], -d.center[2]] };
  return { ...d, mural, noPaint, low: [-d.low[0], d.low[1], -d.low[2]], high: [-d.high[0], d.high[1], -d.high[2]] };
}

