    B.cyl('metal', 'galv', 0.018, 0.16, vx, vy + 0.12, z, { seg: 8 });
    B.tor('gloss', 'coral', 0.1, 0.014, vx, vy + 0.2, z, { rx: HP, rs: 5, ts: 16 });
