      B.push(0, H - 0.22 - i * 0.26, 0, angs[i] + B.r(-0.08, 0.08));
      const prof = [[-L / 2, -Hb / 2], [L / 2 - tip, -Hb / 2], [L / 2, 0], [L / 2 - tip, Hb / 2], [-L / 2, Hb / 2]].map((p) => [p[0] * dir, p[1]]);
