    B.tube('metal', 'galv', [P3(x, y, z + s * 0.035), P3(x + Math.cos(a) * (R - 0.05), y + Math.sin(a) * (R - 0.05), z + s * 0.004)], 0.0026, { radial: 3 });
  }
}
function bike(B, frame, basket = false) {
