  for (const s of [-1, 1]) { fr(P3(bb[0], bb[1], s * 0.03), P3(rw[0], rw[1], s * 0.05), 0.011); fr(P3(st[0] + 0.03, st[1] - 0.08, s * 0.02), P3(rw[0], rw[1], s * 0.05), 0.01); }
  for (const s of [-1, 1]) fr(P3(hb[0], hb[1], s * 0.03), P3(fw[0], fw[1], s * 0.05), 0.012);
