  for (const s of [-1, 1]) { B.cyl('rubber', 'rubber', 0.017, 0.11, ht[0] - 0.035, hy, s * 0.24, { rx: HP, seg: 8 }); B.tube('metal', 'darksteel', [P3(ht[0] + 0.01, hy, s * 0.18), P3(ht[0] + 0.07, hy - 0.02, s * 0.2)], 0.005, { radial: 3 }); }
