    }
    const yAt = (x) => Hh + (end - Hh) * (x / L) - sag * (1 - Math.pow((2 * x) / L - 1, 2));
    const pts = []; for (let i = 0; i <= 18; i++) { const x = (i / 18) * L; pts.push(P3(x, yAt(x), 0)); }
