export function registerPropPacks(packs) {
  const keys = new Set(Object.keys(D)), spins = new Map(SPIN_TEMPLATES);
  const registered = new Map(REGISTERED_PACKS), descriptions = PROP_TYPES.slice();
  try { for (const [id, register] of packs) registerPropPack(id, register); }
  catch (error) {
