  // ------------------------------------------------------------------------------------------ geometry helpers
  // tiny builder (same contract as props.js GB: triangles auto-orient to the supplied outward normals)
  class GB {
    constructor() { this.p = []; this.n = []; this.c = []; this.idx = []; }
