        B.box('metal', shade(strC, 0.85), L + 0.3, 0.04, 0.1, mid[0] - nx * 0.37 + dx * -0.15, mid[1] - ny * 0.37 + dy * -0.15, ze + out * 0.05, { rz: ang, r: 0.01 });
        noShadow(B, () => {
